export const practiceMeta={slug:'training/practice',title:'Pretraining: Experiments and Run Design',description:'Turn a capability objective into controlled ablations, a frozen recipe, a feasible token budget and a recoverable full-scale run.',date:'2026-06-02',updated:'2026-10-18',topicPath:['training'],tags:['pretraining','ablation','scaling ladder','efficiency gain','Smol','context extension','goodput','determinism','checkpoint','run design'],learningGoals:['Design informative proxies and confirm their scale transfer.','Account for compute, data, context and recovery without double counting.','Rehearse full-state restart and measure committed progress.'],related:['training/data','training/scaling','training/optimization','training/stability','training/parallelism'],prototype:false,visibility:'public',kind:'dense-topic'};
export const practiceAliases=["systems/infrastructure/choosing-an-llm-training-framework","ai/training/scaling/scaling-ladders-and-efficiency-gain","ai/training/scaling/progressive-context-extension","ai/evaluation-experimentation/llm-ablation-strategy","ai/training/smol-training-playbook-foundations","ai/training/optimization/rules-of-engagement-for-llm-training","systems/infrastructure/goodput-determinism-and-fault-tolerance","ai/training/smol-training-playbook","ai/training/pretraining-system-design-interview-guide"];
export const practiceSections=[['compass','Define what the run must achieve'],['baseline','Build a baseline you can trust'],['proxy','Choose what the proxy preserves'],['matching','Match the resource that answers the question'],['ladder','A ladder tests scale transfer'],['efficiency','Convert a loss improvement into equivalent cost'],['experiment','Promote an experiment through explicit gates'],['freeze','Freeze a recipe, not just hyperparameters'],['budget','Start from committed model compute'],['worksheet','A 256-GPU run-design worksheet'],['size','Choose capacity and exposure together'],['architecture','Make the architecture executable'],['data','Version the stream and its safeguards'],['loader','Treat input delivery as part of the run'],['batch','Make batch and memory accounting explicit'],['topology','Map ownership onto the cluster'],['framework','Choose a framework with a real rehearsal'],['rehearsal','Increase operational risk in stages'],['context','Pay for long context where it matters'],['context-lab','Compare staged and always-long compute'],['context-evidence','Read the context recipes with their scope'],['smol','The connected Smol development loop'],['annealing','Branch late data changes from one checkpoint'],['post-training','Keep the base-to-assistant contract intact'],['frontier','Two frontier schedules and their boundaries'],['metrics','MFU, hardware utilization and goodput differ'],['checkpoint','Design the durable checkpoint transaction'],['restart','Watch a restart preserve or change the run'],['determinism','Specify the reproducibility contract'],['interval','Balance checkpoint pauses against replay'],['elastic','Continue with fewer devices only under a contract'],['telemetry','Join model and system telemetry'],['evaluation','Use evaluation gates throughout the run'],['incidents','Respond to an incident with evidence'],['serving','Validate the exported artifact'],['sources','References and connected notes']];
const smol='https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook',mai='https://microsoft.ai/wp-content/uploads/2026/06/main_20260602_2.pdf',deepseek='https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash/blob/main/DeepSeek_V41_Tech_Report.pdf';
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('<div class="dense-table-wrap">','<div class="dense-table-wrap" tabindex="0" role="region" aria-label="Scrollable comparison table">');
const scene=(id,title,controls,body,play=false)=>`<div class="topic-scene" data-practice-lab="${id}"><h3>${title}</h3>${controls}${play?'<div class="dense-actions"><button type="button" data-play>Play</button><button type="button" data-reset>Replay</button></div>':''}<div data-body>${body}</div></div>`;
function budgetBody(rate,parameters,goodput){const b=runBudget({rate,parameters,goodput:goodput/100});return `<svg viewBox="0 0 440 270" role="img" aria-label="Ninety days split into experiments eight, rehearsal seven, main run seventy-five and contingency ten percent"><text x="20" y="30">90 allocated days · fixed 256 GPUs</text>${[['Experiments',8,'#eadbad'],['Rehearsal',7,'#bad6fa'],['Main run',75,'#bd738e'],['Contingency',10,'#93748a']].map(([name,p,c],i)=>`<text x="20" y="${65+i*48}">${name}: ${p}%</text><rect x="245" y="${47+i*48}" width="${p*2.2}" height="25" fill="${c}"/>`).join('')}</svg><p>Assumed healthy model rate: ${rate} TFLOP/s per GPU. Main-run goodput: ${goodput}%. Parameters: ${parameters}B. Main window: ${b.mainDays.toFixed(1)} days; equivalent healthy time: ${b.idealDays.toFixed(2)} days.</p><p>Committed model compute: ${b.compute.toExponential(3)} FLOPs. Under 6PT: ${ (b.tokens/1e12).toFixed(3)}T tokens, or ${b.ratio.toFixed(0)} tokens per parameter.</p><p>This is an assigned planning scenario, not a measured H100 rate or an optimal allocation. Contingency is outside the 75% main window. Goodput discounts overhead within that window. If your measured rate already includes those stalls and replay, do not discount it again.</p>`;}
function contextBody(main,multiplier){const c=contextCost(main/100,multiplier);return `<svg viewBox="0 0 440 265" role="img" aria-label="Normalized per-token cost, short ${c.short}, staged ${c.staged.toFixed(3)}, always long ${c.long}"><text x="20" y="30">Fixed tokens · one cost scale</text>${[['Always short',c.short,'#eadbad'],['Staged',c.staged,'#bad6fa'],['Always long',c.long,'#bd738e']].map(([name,v,color],i)=>`<text x="20" y="${64+i*68}">${name}: ${v.toFixed(3)}</text><rect x="20" y="${76+i*68}" width="${v*100}" height="22" fill="${color}"/>`).join('')}</svg><p>Short length L₀=4K; extension ${multiplier*4}K. ${main}% of tokens use L₀. Assigned per-token cost is 1+0.1·L/L₀. Staged cost is ${c.relative.toFixed(3)}× always-short; always-long is ${c.always.toFixed(3)}×. Staging saves ${(100*c.saving).toFixed(1)}% versus always-long in this model.</p><p>The linear term represents non-attention arithmetic. The length-dependent term represents dense attention at fixed total tokens. ${main===100?'At 100%, no tokens train at the extension length. ':''}This comparison predicts no accuracy, retrieval quality, activation memory or wall-clock speedup. Sparse attention and different kernels require different cost models.</p>`;}
function recoveryBody(step,policy){const t=recoveryTrace(policy),f=t.frames[step];return `<svg viewBox="0 0 440 305" role="img" aria-label="${f.label}; logical step ${f.step}, durable step ${f.durable}, executed updates ${f.executed}"><text x="20" y="30">${f.label}</text>${[['Logical step',f.step,'#bad6fa'],['Durable step',f.durable,'#eadbad'],['Executed updates',f.executed,'#bd738e']].map(([name,v,color],i)=>`<text x="20" y="${64+i*61}">${name}: ${v}</text><rect x="20" y="${75+i*61}" width="${v*44}" height="22" fill="${color}"/>`).join('')}<text x="20" y="267">Cursor ${f.cursor} · RNG ${f.rng} · moment ${f.m}</text><text x="20" y="293">Weight accumulator ${f.w}</text></svg><p>Step ${step} of 10. ${policy==='full'?'Policy: restore full state at step 3.':policy==='moments'?'Policy: reset the moment at step 3 restore.':'Policy: reset loader and RNG at step 3 restore.'} End-state matches uninterrupted reference: <strong>${t.correct?'yes':'no'}</strong>. All policies execute eight updates to reach logical step six; two pre-failure updates are replayed.</p><p>Toy update: sample=cursor+1; RNG←(5·RNG+1) mod 16; m←2m+sample+RNG; w←w+m. Start cursor=0, RNG=1, m=w=0. This exact integer accumulator demonstrates state dependence. It is not Adam, a loss curve or a GPU recovery benchmark.</p>`;}
export function practiceReader(link){return topic(practiceMeta,practiceSections,'A training run is an experiment whose result must remain valid after weeks of execution.',`
<p>A promising proxy result is not yet a training recipe. The result must survive a change of scale, a longer data stream and a real distributed system. A finished run must also produce a checkpoint that can be evaluated, resumed and served.</p><p>Start with the capability objective. Use controlled experiments to reduce uncertainty. Then connect compute, data, architecture and recovery into one executable plan. The later sections retain the Smol development pipeline and source-specific frontier examples.</p>
${section('compass','Define what the run must achieve',`<p>Write three decisions before choosing a model: why train, what capabilities matter, and how the model will be used. A code base model for local deployment has different constraints from a general multilingual assistant.</p><p>Specify task families, languages, context, latency, memory, licensing, hardware and deadline. Define evaluation sets and hard constraints. A weighted held-out negative log-likelihood (NLL) objective is useful for cheap development, but it does not replace generation, execution or safety checks.</p><p>MAI explicitly combines Coding, STEM, Math, General and Multilingual evaluations with weights 0.5, 0.175, 0.175, 0.1 and 0.05. These are capability priorities, not training-data proportions. Do not copy them without the same objective. ${cite(mai,'MAI §§2.2–2.3')}</p><p>Predeclare what would justify another experiment and what would justify freezing. Exploration consumes the same calendar and compute needed to finish the run. Prefer high-leverage questions about data, scale or a bottleneck over many tiny improvements with uncertain transfer.</p><p>First compare training from scratch with continuing an existing checkpoint or using an existing model. Training is justified only if the capability, rights or deployment requirements warrant its cost. State acceptable failure risk, privacy/audit requirements, checkpoint cadence and replacement-node policy alongside hardware and deadline.</p>`)}
${section('baseline','Build a baseline you can trust',`<p>First make a cheap known-good configuration reproducible. Fix tokenizer, data snapshot, packing, masks, objective reduction, initialization, optimizer, schedule and evaluation. Verify the distributed implementation against a small reference.</p><p>A baseline is a versioned object. Record its code, configuration, random seeds, loader state and measured cost. An accepted change becomes the next baseline; do not compare new experiments against several silently different recipes.</p><p>Use direct intermediate checks. Decode fixed examples and inspect repetitive output, special tokens, reasoning modes and tool formatting. Such checks reveal bugs that NLL can miss. They are debugging evidence, not a substitute for held-out quantitative evaluation.</p><p>Inspect system prompts and multi-turn continuations explicitly. A missing system message, broken chat template or style failure can leave aggregate loss nearly unchanged. Interactive inspection helps find these bugs; a few good examples do not establish general capability.</p>`)}
${section('proxy','Choose what the proxy preserves',`<p>Two cheap experiments answer different questions. Train the intended architecture for fewer tokens to check early behavior and implementation. Train a smaller model to explore many alternatives. Neither automatically predicts the final ranking.</p><p>Preserve the mechanism being tested. A routing experiment needs representative experts and allocation. A data experiment needs representative mixture, repetition and token horizon. A context experiment needs the attention operator, positions and masks used at deployment.</p><p>A small positive result is a candidate for promotion, not proof. A negative result can be a useful filter, but delayed learning or a scale interaction can reverse it too. Reject a broken implementation confidently; reject a research idea only within the tested regime.</p><p>High-quality specialized data can help a larger model while harming a small proxy. Conversely, a source can look useful early and become repetitive later. The original Smol material uses arXiv as an example of capacity-dependent value; treat the observation as recipe-specific.</p>`)}
${section('matching','Match the resource that answers the question',`${table('An experiment has a budget contract',['Question','Match or report','Uncontrolled difference'],[['Architecture quality','Training FLOPs, data/evaluation, parameter convention','Different active capacity or exposure'],['Operational advantage','Wall time or GPU-hours on stated stack','Unoptimized kernels or topology'],['Data source value','Realized target tokens, epochs and held-out sets','Different novelty/repetition'],['Optimizer/schedule','Update and token horizon, tuned ranges','One method receives more tuning'],['Late data injection','Common parent and matched continuation','Different base checkpoints']])}<p>Equal parameters, equal tokens and equal FLOPs are not always simultaneously possible. State the comparison rather than call it fair without a denominator. Count active versus stored mixture-of-experts (MoE) parameters, embeddings, attention and recomputation consistently.</p><p>Use repeated seeds or paired branches where practical. Preserve failed runs and report uncertainty. A tiny loss difference may not exceed run noise. Validate interactions after isolated ablations: a better tokenizer, mixture and schedule can change one another's ranking.</p><p>Architecture labels can hide budget changes. Untying embeddings adds a separate output matrix. Head sharing changes key/value projection capacity. Changing the feed-forward expansion changes both stored capacity and arithmetic. Recalculate the budget before attributing a quality gain to the mechanism.</p>`)}
${section('ladder','A ladder tests scale transfer',`<p>Train several sizes under a defined family and compare curves. Keep the tokens-per-active-parameter (TPP) regime fixed for a particular ladder when that is the intended experiment. Use a second horizon if the final run is much more heavily trained.</p><p>Keep architecture and optimizer families, the data objective and the training-density rule consistent within the ladder. Changing any of them changes the comparison. Width, depth, optimization, data saturation and systems overhead can alter rankings as scale grows.</p><p>MAI uses 100–200 TPP for many architecture ablations and discusses 500–1,000 TPP runs. Its label “near Chinchilla” should not become the universal 20-TPP reference. Its reported 30T/35B final backbone exposure is about 857 TPP; the active-parameter denominator matters.</p><p>Hold out a larger confirmation point. A fitted curve can conceal poor extrapolation. Data-mixture rankings can invert with scale: MAI reports a small-scale STEM-heavy winner losing to a code-heavier mixture at larger scale.</p><p><a href="${link('training/scaling')}#ladders">Scaling Laws →</a> owns frontier fitting and allocation. Here the ladder is a decision gate: an idea progresses only when the intended regime supports it.</p>`)}
${section('efficiency','Convert a loss improvement into equivalent cost',`${eq(String.raw`\begin{aligned}f(C)&=AC^{-\alpha}+E\\C_{\rm equivalent}&=\left(\frac A{L'-E}\right)^{1/\alpha},\qquad\operatorname{EG}=\frac{C_{\rm equivalent}}{C'}\end{aligned}`,'A>0, α>0, C′>0 and L′>E. E is a fitted floor, not measured true entropy.')}<p>Efficiency gain asks how much the baseline would spend to match the candidate's loss. ${inlineMath(String.raw`\operatorname{EG}=1.3`)} means 30% more baseline cost than candidate cost. The candidate saves ${inlineMath(String.raw`1-\frac1{1.3}\approx23.1\%`)} against that equivalent baseline, not 30%.</p><p>Take an illustrative candidate cost of 100 units and an equivalent baseline cost of 130 units. Both costs refer to the same target loss.</p>${table('One cost difference, two percentage denominators',['Question','Reference cost','Relative difference'],[['How much extra does the baseline need?','Candidate: 100',inlineMath(String.raw`\frac{130-100}{100}=30\%`)],['How much does the candidate save?','Equivalent baseline: 130',inlineMath(String.raw`\frac{130-100}{130}\approx23.1\%`)]])}<p>For a normalized example, use ${inlineMath(String.raw`f(C)=1+C^{-0.5}`)}. At ${inlineMath(String.raw`C'=4`)} and ${inlineMath(String.raw`L'=1.4`)}, equivalent baseline cost is 6.25 and ${inlineMath(String.raw`\operatorname{EG}=1.5625`)}. These assigned numbers illustrate the inverse, not a measured model.</p><p>Fit FLOP-based and time-based curves separately. MAI's shared-expert MoE-every-layer comparison reports weighted ${inlineMath(String.raw`\operatorname{EG}_{\rm FLOPs}=1.03`)} but ${inlineMath(String.raw`\operatorname{EG}_{\rm Time}=0.82`)} against its interleaved baseline. The latter says the actual stack loses the modeled advantage. It does not prove the architecture can never be optimized.</p><p>Inverse estimates become fragile near the floor and outside the fit range. Include fit uncertainty, cost convention and the scale range. Do not infer an equivalent cost for ${inlineMath(String.raw`L'\le E`)} from this equation.</p>`)}
${section('experiment','Promote an experiment through explicit gates',`${table('Example decision sequence; engineering procedure, not measured results',['Gate','Evidence to retain','Decision'],[['0 · Correctness','Reference loss/gradient, masks, data IDs, restart','Repair bugs before ranking'],['1 · Cheap screen','Matched proxy and noise estimates','Reject within scope or shortlist'],['2 · Stronger proxy','Longer horizon, representative repetition','Check persistence and interactions'],['3 · Ladder','Several scales and held-out larger run','Check extrapolation and ranking'],['4 · Stack rehearsal','Throughput, memory, checkpoint and failure tests','Price the operational cost'],['5 · Freeze','Versioned recipe, objective and stop conditions','Start the main run']])}<p>Choose experiment order by expected information per resource. Screen dimensions with a plausible large effect first: mixture, architecture shape, optimizer/schedule and a dominant system bottleneck. A tiny theoretical gain can cost more in implementation and delayed start than it returns.</p><p>The gates are not a mandatory six-run ceremony. Reuse evidence when its conditions match. Write the unresolved assumption at promotion rather than hide it behind a passing benchmark.</p><p>Useful early candidates include embedding tying, attention head sharing, depth/width and feed-forward shape, optimizer/scheduler families, learning rate, batch size and mixture weights. Choose a candidate because it tests an unresolved mechanism, not because the sweep is easy to automate. Change one component or a small declared group while fixing the remaining baseline.</p><p>Set an exploration deadline and a promotion threshold before seeing the results. Stop when further uncertainty reduction is worth less than the delay and reserved run resources. This is a resource decision, not proof that the chosen recipe is globally optimal.</p>`)}
${section('freeze','Freeze a recipe, not just hyperparameters',`<p>Record model shape, tokenizer, special tokens, data manifests, mixture/caps, packing/masks, optimizer groups, precision and schedules. Include batch semantics, parallel layout, checkpoint format, evaluation harness and the serving conversion.</p><p>Freezing limits uncontrolled variation; it does not forbid responding to a correctness incident. Record any authorized intervention as a new run branch with its parent and reasons. Keep a recovery plan and a conservative fallback.</p><p>Prefer a broad stable optimum over a narrow fragile win when gains are uncertain. Warmup–stable–decay (WSD) offers a long extendable stable phase and a later decay branch. Cosine can be appropriate for a fixed horizon. Neither is universally superior. <a href="${link('training/optimization')}">Optimization →</a></p><p>Small high-quality datasets can be reused deliberately with measured caps. Reuse is not infinite novelty. Reserve resources for annealing, context extension, recovery, final evaluation and the required post-training stages.</p>`)}
${section('budget','Start from committed model compute',`${eq(String.raw`\begin{aligned}F_{\rm model}&\approx6PT\\F_{\rm available}&=n\,r_{\rm model}\,t_{\rm main}\,g\\6PT&\le F_{\rm available}\end{aligned}`,'P is the matching parameter count; T is processed tokens; n is devices; r_model is healthy model FLOP/s per device; g is main-window goodput.')}<p>The 6PT rule approximates dense non-embedding forward/backward arithmetic. Attention, embeddings, sparse structure and other operations can matter. Full activation recomputation can raise executed arithmetic toward an 8PT approximation in some settings.</p><p>Do not charge recomputation twice. Model FLOP utilization (MFU) uses useful model arithmetic rather than all recomputed hardware work. If the measured rate is already a model-FLOP rate, its time penalty already appears there. Hardware-FLOP rate needs the executed-work model instead.</p><p>A peak specification multiplied by an assumed MFU is a scenario, not a measurement. Use a representative full-stack rehearsal and a lower/base/upper range. Distinguish a healthy-step rate from an end-to-end rate that already includes failures and checkpoints.</p>`)}
${section('worksheet','A 256-GPU run-design worksheet',`${scene('budget','Allocate the calendar before promising tokens','<label>Healthy model TFLOP/s per GPU<input type="range" aria-label="Healthy model throughput" min="100" max="400" step="10" value="200"></label><label>Dense parameters<select aria-label="Planned model size"><option value="3">3B</option><option value="7" selected>7B</option><option value="13">13B</option></select></label><label>Main-window goodput<input type="range" aria-label="Main run goodput" min="50" max="100" step="5" value="90"></label>',budgetBody(200,7,90))}<p>The worked constraint is 256 GPUs for 90 days. One feasible allocation is 8% exploration, 7% rehearsal, 75% main training and 10% contingency. These shares sum to 100%; independently chosen percentage ranges may not.</p><p>At the default assigned rate, the 7B scenario gives about 6.40T tokens under the approximation. That arithmetic is not a recommendation to train for that many tokens. Check corpus novelty, repetition, inference economics, final context and other stages first.</p><p>If context extension shares the main window, split the compute explicitly between lengths. If post-training is in the same allocation, reserve it before spending the main budget. Do not claim a base-training token budget that uses someone else's reserved resources.</p>${table('Three useful planning starting points',['Given','Derive first','Keep explicit'],[['Device count and deadline','Achieved compute and feasible parameter/token pairs','Experiments, recovery and final stages'],['Money budget and target size','Device-hours, useful throughput and attainable tokens','Hardware, storage and engineering costs'],['A slow or unstable existing run','Phase timing and a controlled failing branch','Correctness before throughput tuning']])}<p>For the coding scenario, verify the accelerator variant and interconnect, whether existing weights can be continued, and whether the deadline includes experiments. Evaluate licensed repository context, documentation and permitted issue/patch histories, not just isolated files. The last chronological checkpoint is not automatically the best export.</p>`)}
${section('size','Choose capacity and exposure together',`<p>Several parameter/token pairs can fit the same approximate compute. A larger model learns from fewer tokens under a fixed budget. A smaller, more heavily trained model may reduce recurring inference cost, even off the pretraining-compute frontier.</p><p>Compare dense and MoE only after accounting for total state, active arithmetic, communication, serving behavior and implementation maturity. A large stored parameter count does not determine the token budget or guarantee a quality advantage.</p><p>Use scaling estimates to narrow candidates, then verify actual throughput and data limits. A 3B on-device target is not chosen by the same objective as a large hosted coding model. <a href="${link('training/scaling')}#lifecycle">Lifecycle allocation →</a></p>`)}
${section('architecture','Make the architecture executable',`<p>Specify depth, width, feed-forward expansion, activation, normalization, initialization, vocabulary, tying and attention. Grouped-query attention (GQA) can reduce KV-cache cost; its training speed and quality still require a matched test. Choose positions and masks for the intended lengths.</p><p>For coding, audit tokenization of indentation, whitespace, operators, Unicode, separators and fill-in-the-middle controls. Measure tokens per source/language. A larger vocabulary changes embedding memory and projection cost.</p><p>Architecture and kernels are coupled. A new operation can change fusion, communication, activation storage and the best layout. Prototype correctness before measuring speed. <a href="${link('models/transformers')}">Transformer Architecture →</a> · <a href="${link('models/attention')}">Attention →</a> · <a href="${link('models/tokenization')}">Tokenization →</a></p><p>For a conservative dense recipe, specify AdamW, decoupled weight decay, warmup and decay, clipping, packing, selected high-precision operations and residual initialization. Test alternatives through a ladder. Optimizer settings, architecture and kernel implementation form one experiment, not independent defaults.</p>`)}
${section('data','Version the stream and its safeguards',`<p>Keep source rights and provenance through parsing, quality filtering, safety checks, deduplication, decontamination and tokenization. Freeze the resulting manifests and held-out splits. Track raw inventory, useful unique tokens and expected passes separately.</p><p>For code, handle repositories, forks, generated/vendor files, licenses, secrets and build/test validity. Repository and temporal separation can reduce leakage. A passing test is not proof that generated code is safe or licensed.</p><p>Define token-based mixture weights, source caps and realized exposure. Document probability, sequence probability and target-token share differ. Loss masks and reduction affect gradient contribution too. Audit domain losses rather than rely on one global average.</p><p><a href="${link('training/data')}">Training Data →</a> owns curation, exposure, mixture search and source-conditioned evidence. The run design records exactly which version of that policy the loader executes.</p><p>Register immutable raw snapshots with timestamps, source, license and lineage. Audit correctness, coherence, information density, authority, parse integrity, difficulty and harmful content separately. For synthetic data, record the generator and verifier. Deduplication needs a declared unit and threshold: documents, spans, repository forks and evaluation overlap are different decisions.</p><p>Do not remove legitimate repeated conventions or rare-domain coverage merely to maximize a deduplication rate. Version fixed, temperature-based, quality-weighted or adaptive sampling policies. Record each mixture transition with consumed tokens and checkpoint lineage. Evaluate both specialization gains and general-domain regression.</p>`)}
${section('loader','Treat input delivery as part of the run',`<p>A correct stream can still leave GPUs idle. Use sequential shards, local caching, prefetch, decompression and bounded queues appropriate to the storage system. Measure CPU saturation, queue depth, cache misses and input wait time.</p><p>Checksum and validate shards. Quarantine a corrupt input with an explicit policy and logged source impact. Unrecorded skipping changes the experiment. Backpressure must not silently reorder or duplicate samples.</p><p>Compare a synthetic resident input with the real loader to isolate a bottleneck. Faster synthetic steps implicate the input path, but not one particular storage component. Keep the actual loader cursor, sampler, mixture counters and packing buffers in the restart contract.</p>`)}
${section('batch','Make batch and memory accounting explicit',`${eq(String.raw`B_{\rm sequences}=b_{\rm micro}\,a_{\rm accumulation}\,n_{\rm data\ parallel},\qquad T_{\rm step}=B_{\rm sequences}S`,'For equal full-length sequences. Count non-padding input and supervised target tokens separately when masks or packing change the denominator.')}<p>Tensor, pipeline, context and expert ranks are not automatically additional independent examples. Count the data-parallel replicas that own distinct batch portions. Specify whether loss is token-mean or sequence-mean before accumulating gradients.</p>${eq(String.raw`\begin{aligned}M_{\rm total}&=M_{\rm params}+M_{\rm grads}+M_{\rm optimizer}\\&\quad+M_{\rm activations}+M_{\rm temporary}+M_{\rm fragmentation}\end{aligned}`,'Non-overlapping peak-memory categories on the same device and at the same execution point. Master weights and communication buffers must be assigned once, not omitted or counted twice.')}<p>Memory includes parameters, gradients, moments, any master copy, activations, communication workspaces, temporary tensors and allocator headroom. Precision and sharding change each term. A universal bytes-per-parameter estimate does not cover this full state.</p><p>Measure peak memory at representative length and batch, not only steady allocations. Use activation recomputation/offload and optimizer/state sharding under an explicit trade-off. More accumulation can fit memory while lengthening the step or changing overlap.</p><p>Increasing batch size changes gradient noise, update count and communication frequency. Retune learning rate and token schedule when needed, rather than treating higher utilization as free optimization improvement. Long-context activations can dominate where short-context optimizer state previously set the limit.</p>`)}
${section('topology','Map ownership onto the cluster',`<p>Place frequent large communication on the fastest links where possible. Map tensor, pipeline, data/state, context and expert parallelism to actual device groups and node topology. Do not apply a generic “3D parallelism” label without explaining ownership.</p><p>For each collective ask: which ranks participate, what bytes move, how often, which dependencies wait, what overlaps, and what happens to the slowest rank? Pipeline bubbles, expert imbalance and cross-node reductions need different fixes.</p><p>Benchmark the real shape and kernel stack. More devices can reduce efficiency through smaller GEMMs or added communication. <a href="${link('training/parallelism')}">Distributed Training and Parallelism →</a> owns dimensions, sharded matrices and scheduling mechanisms.</p>`)}
${section('framework','Choose a framework with a real rehearsal',`${table('Selection dimensions; not a current product ranking',['Dimension','Question to test'],[['Features','Does the exact model support its masks, precision, routing and layout?'],['Robustness','Can it restore optimizer/data state and survive faults?'],['Throughput','Does the representative end-to-end stack meet budget?'],['Modifiability','Can the team maintain the required kernels and behavior?'],['Support','Who owns bugs, version changes and recovery?']])}<p>Megatron, DeepSpeed or an internal stack can each be appropriate under different needs. Framework reputation does not settle the choice. Pin versions and test the intended workload rather than repeat an old speed comparison as a current ranking.</p><p>Read the execution path before adopting the stack. Trace an optimizer update, a distributed checkpoint and a restart. Repeat the trace with MoE, context parallelism and custom numerics enabled. Clear abstractions help locate throughput drops and distributed bugs; a simple baseline alone does not establish that clarity.</p><p>An internal framework gives direct access to its maintainers, but also assigns maintenance and recovery to the organization. An external framework brings community support and established implementations, but its abstractions can constrain changes. Identify an owner for critical bugs and upgrades before the run.</p><p>Mature stacks often trade ease of modification for operational coverage. Smaller stacks can shorten experimentation, but require more validation before a long run. These are tendencies, not current product rankings. Compare implementation time, debugging effort, instability and runtime cost on the same representative workload.</p><p>MAI's YOLO sharding annotations describe ownership; they do not automatically inject all communication. That design makes synchronization explicit. It is not a promise that every annotation-based framework has the same semantics.</p><p>Features, correctness, stability and recovery interact, but their product is a metaphor, not a measured dimensional throughput equation. A stack without an indispensable feature is infeasible even if its simple baseline is fast.</p>`)}
${section('rehearsal','Increase operational risk in stages',`<ol><li>One-device correctness: verify forward loss, masks, targets and gradients.</li><li>Small sharded run: compare reductions, optimizer updates and precision.</li><li>Multi-node run: test topology, collectives, data delivery and stragglers.</li><li>Soak run: inspect thermal behavior, memory growth and long-lived processes.</li><li>Actual-scale rehearsal: measure throughput, checkpoint stalls and restoration.</li><li>Main run: start from the frozen manifest with owners and response gates.</li></ol><p>Exercise resume before committing the expensive run. A checkpoint that has never been restored is an untested artifact. Fault injection must use an authorized test environment, not interrupt a production job without a plan.</p><p>Reserve real resources for rehearsal. A long run can expose bugs that a few healthy steps cannot. The Smol playbook's tensor-parallel seeding incident illustrates why initialization and rank state deserve early checks; the retained original places the restart around one trillion tokens.</p>`)}
${section('context','Pay for long context where it matters',`<p>At fixed sequence count, dense attention grows quadratically with length. At fixed total tokens, there are fewer sequences, so its per-token arithmetic grows roughly linearly with length. These are different comparisons.</p><p>Train the broad representation at a cheaper length when the objective permits. Then extend with validated positions, masks, packing, learning rate and data. Test long-range use, not only whether the model accepts a larger input.</p><p>A staged plan uses short or moderate main training, then an intermediate extension and a final target-length stage. Mid-training names a position in the pipeline; it is not necessarily supervised fine-tuning. Repacking keeps source proportions while exposing longer documents, such as repositories, books and technical articles. It changes sequence construction, not the underlying source identity.</p><p>Repacking the same broad mixture can reduce a distribution change, but it does not preserve every attention relation. Document boundaries, loss masking and cross-document access still matter. Long-context NLL, retrieval, generation and short-context regression are separate tests.</p><p>Choose the main length from measured throughput and memory on the intended stack. Reserve extension compute separately. Changes in length also affect communication, activation storage and checkpoint cost. A favorable arithmetic estimate does not guarantee the final latency or quality.</p>`)}
${section('context-lab','Compare staged and always-long compute',`${scene('context','Separate token allocation from sequence length','<label>Short-context token share<input type="range" aria-label="Short context token share" min="90" max="100" step="1" value="99"></label><label>Extension length<select aria-label="Extension length"><option value="8">32K</option><option value="16" selected>64K</option></select></label>',contextBody(99,16))}${eq(String.raw`\operatorname{cost}_{\rm sequence}\approx aL+bL^2,\qquad\operatorname{cost}_{\rm fixed\ tokens}\approx T(a+bL)`,'Assigned dense-attention approximation. Hardware time and sparse attention can differ.')}<p>With fixed token shares qᵢ and lengths Lᵢ, sum T·qᵢ·(a+bLᵢ). Do not apply a quadratic length multiplier to every token when the comparison holds total tokens fixed. The static default is 1.115 cost units staged versus 2.6 always-long.</p>`)}
${section('context-evidence','Read the context recipes with their scope',`<p>The Smol material describes 4K→32K→64K training, with roughly 50B-token context stages and fresh schedules. The Smol ablation finds specialized books/articles/synthetic long data no better than its broad baseline in that experiment. The suggested reason is that the baseline already contains long web/code documents.</p><p>In that Smol experiment, fresh extension schedules were better than attaching the stages to the tail of the main decay. This comparison motivates a separate adaptation trial, not a universal schedule rule. Positional calibration, distant retrieval and attention behavior can all change; NLL alone does not identify which mechanism improved.</p><p>For its tested extrapolation, 64K→128K with YaRN works better than 32K→128K; 256K degrades. Adjusted base frequency (ABF) in rotary positional embeddings (RoPE) and YaRN scaling need joint tuning. These findings do not certify every model at those lengths. <a href="${link('models/position')}">Positional Encodings →</a></p><p>MAI Appendix B reports most extension NLL improvement in the first 1–10% of iterations. Its proposed calibration explanation is a hypothesis, not proof that no new capability is learned. The Appendix's final recipe states 140B tokens at 256K; the main phase table uses 150B at 262,144. Keep both source scopes visible rather than silently reconcile them.</p><p>Preserve retrieval and generative QA tests alongside NLL, short-context quality and per-domain checks. Fast adaptation in one report is evidence for a staged trial, not a universal extension budget.</p><p>MAI reports a staged-versus-always-long comparison and limited short-context degradation under its tested recipe. That supports measuring a cheaper staged candidate, not assuming equivalence in a new model. Keep a broad mixture and objective where appropriate, but explicitly test short-context regression after extension.</p>`)}
${section('smol','The connected Smol development loop',`<p>The playbook starts from a compact deployment goal: a 3B dense Llama-style model for multilingual, coding and mathematical use. It connects architecture and data selection to the later assistant pipeline rather than optimize only pretraining loss.</p><p>GQA provides a practical cache trade-off. Hybrid no-positional-embedding (NoPE)/positional attention and intra-document masking are separate choices tested for the intended context behavior. AdamW and flexible schedules provide an operational baseline. Learning-rate and batch scaling rules narrow a search; they do not replace testing.</p><p>Data priorities include preserving English while adding languages, code and math. Early broad exposure and later high-quality material have different roles. Define these changes by tokens and actual loss masks, not just example counts.</p><p>The complete sequence is objective → cheap baseline → ablations → recipe → full run → late data/context stages → SFT → preference optimization → selective reinforcement learning (RL) → serving evaluation. A change earlier in the chain can alter a later stage's behavior. ${cite(smol,'Smol Training Playbook')}</p><p>Smol treats multilingual allocation as a budget trade-off with English and other domains. In its recipe, excessive code early can hurt general evaluations. Broad English-web exposure comes first; higher-quality code/math and reasoning/Q&amp;A enter later. These are recipe-specific observations, not evidence that one source order is universally optimal.</p><p>Its short-context results do not settle long-context architecture: intra-document masks can matter more at longer lengths, and hybrid RoPE/NoPE has to be tested at the intended lengths. GQA balances cache cost against quality within a particular model comparison, not a guaranteed quality ranking for every model.</p>`)}
${section('annealing','Branch late data changes from one checkpoint',`<p>A long stable phase makes late annealing experiments inexpensive relative to retraining from scratch. Save a common parent, inject a candidate source and compare matched decay branches. Keep parent optimizer state, token counts and evaluation fixed where the question requires them.</p><p>This answers whether the source helps at that stage. It does not estimate its value throughout pretraining. A candidate can win through repetition, formatting or altered mixture rather than broad new knowledge. Check held-out domains and exposure.</p><p>Price the candidate's collection, filtering and implementation cost too. A narrow gain that delays the full run may be a poor project decision. Keep both successful and unsuccessful branches for the next recipe.</p>`)}
${section('post-training','Keep the base-to-assistant contract intact',`<p>Establish a supervised fine-tuning (SFT) baseline before adding more optimization. Fix chat templates, turn boundaries, special tokens, reasoning controls, tool schema and which tokens receive loss. Formatting is part of the checkpoint contract.</p><p>The Smol pipeline uses offline preference approaches such as DPO/APO before deciding where RL is needed. Reasoning and direct-answer modes have different length distributions and evaluation needs. Do not treat one mode's benchmark gain as every mode's improvement.</p><p>Verifiable-reward RL can improve task success while increasing output length. Reward design, termination and length pressure matter. A larger scalar reward or longer answer is not automatically a better deployed policy.</p><p>Keep matched base-checkpoint adaptation checks when feasible. Later pretraining is not always better for every transfer task. <a href="${link('training/stability')}#workflow">Checkpoint selection through transfer →</a></p><p><a href="${link('post-training/sft')}">Complete SFT reference →</a> · <a href="${link('post-training/preferences')}">Preference methods →</a> · <a href="${link('post-training/reasoning')}#templates">Hybrid reasoning modes →</a>. The connected notes explain the objectives and implementation contracts.</p><p>The initial SFT “baby baseline” checks mode switching, preserved system prompts and multi-turn reasoning before optimizing benchmark scores. In the Smol account, DPO is an offline baseline and APO improves reasoning in its comparison. This does not establish that either objective dominates on all preference data.</p><p>The /think and /no_think modes change response length, not only the prompt label. Smol reports that verifiable-reward RL on concise mode can still produce long reasoning unless the reward constrains length. Measure correctness and length policy separately for each mode. Long traces can dominate token volume despite being few examples; count supervised targets as well as examples.</p>`)}
${section('frontier','Two frontier schedules and their boundaries',`${table('Reported main/mid-training phases, not a transferable recipe',['Report','Tokens','Context','Devices/stage'],[['MAI main','30T','16,384','8,192 GB200'],['MAI mid 1','3.4T','65,536','8,192 GPUs'],['MAI mid 2, main table','150B','262,144','4,096 GPUs'],['DeepSeek-V4.1 backbone','45T total','64K initially; 1M from 34T','Sparse attention from scratch']])}<p>MAI's midtraining also changes STEM/math/code emphasis. A context change and a mixture change must not be interpreted as one isolated context ablation. Its recipe's AdamW, dropout, clipping and precision details remain in the complete report and the connected optimization/numerics owners.</p><p>DeepSeek-V4.1 reports 100.6M global batch tokens, a 2,000-step warmup, LR ${inlineMath(String.raw`2.6\times10^{-4}`)} through 28T, cosine to ${inlineMath(String.raw`2.6\times10^{-5}`)} by 40T, then constant through 45T. At a constant reported batch, ${inlineMath(String.raw`\frac{45\times10^{12}}{100.6\times10^6}\approx447{,}316`)} updates; that is not GPU-hours.</p><p>It also separates backbone pretraining from frozen-backbone DSpark drafter training. Later DSpark updates track the changing backbone without propagating its objective into the backbone. <a href="${link('execution/speculation')}">Speculative Decoding →</a> owns the drafter mechanism.</p><p>Shared attention state across pipeline boundaries, shadow indexers, microbatch lifetimes, row-sharded Engram tables and prefetch affect run feasibility. Separate vision work and context-rank image balancing also belong to the operational recipe. ${cite(deepseek,'DeepSeek §§2.4.3, 3.1, 4.2')}</p>`)}
${section('metrics','MFU, hardware utilization and goodput differ',`${eq(String.raw`\begin{aligned}\operatorname{MFU}&=\frac{\text{useful model FLOP/s}}{\text{stated peak FLOP/s}}\\r_{\rm committed}&=\frac{\text{accepted logical tokens}}{\text{total elapsed seconds}}\\g_{\rm duration}&=\frac{T_{\rm ideal}}{T_{\rm wall}}\end{aligned}`,'Define the useful-work and ideal-rate conventions. The last quantity is dimensionless; token goodput is a rate.')}<p>Hardware FLOP utilization can include recomputed operations. MFU does not automatically price startup, rollback or time outside the measured stepping window. A run can show healthy kernel utilization and still waste substantial allocated time.</p><p>Duration goodput measures time relative to an explicit ideal reference. Checkpoint pauses, replay, restart, degraded placement and silent slowdowns reduce it. It is not automatically GPU utilization or an absolute measure independent of the chosen reference rate.</p><p>Track committed progress separately from attempted updates. A dashboard that counts repeated work as new tokens can falsely show a fast run. A sustained MFU regression is worth investigation even without a crash.</p>`)}
${section('checkpoint','Design the durable checkpoint transaction',`<p>Store weights, optimizer moments, schedules, scaler, steps/tokens, random-number generator (RNG) streams, sampler/loader cursors, mixture and packing state. Include topology/sharding metadata, code/version lineage and FP8 scaling history when used.</p><p>Asynchronous saving overlaps work with I/O, but it must snapshot a consistent logical step. Retain buffers until writes finish. Distributed shards need a complete commit manifest, checksums and a verified readable checkpoint before declaring durability.</p><p>A later incomplete save must not replace the last valid recovery point. Define retention, replicated storage and read validation. Checkpoint portability across different layouts is a separate capability from restoration on the original layout.</p><p>For replicated checkpoint state, one validated storage read followed by a broadcast can reduce many workers reading the same bytes. Sharded state still needs its correct owners. Bound the broadcast traffic and verify version, completeness and checksums before using the restored state. Less storage pressure does not waive the checkpoint transaction.</p><p>Hot standby can reduce startup latency by replicating appropriate state and managing replacement workers. It does not remove communication, correctness or state-ownership obligations. Watchdogs and coordinated failure handling must avoid divergent ranks continuing incompatible steps.</p>`)}
${section('restart','Watch a restart preserve or change the run',`${scene('restart','Logical progress can roll back while compute keeps accumulating','<label>Execution event<input type="range" aria-label="Recovery event" min="0" max="10" step="1" value="0"></label><label>Restore policy<select aria-label="Restore policy"><option value="full">Full state</option><option value="moments">Reset moment only</option><option value="loader">Reset loader and RNG only</option></select></label>',recoveryBody(0,'full'),true)}<p>Save at step 3; fail after step 5; restore step 3; execute steps 4–6; commit step 6. The logical run advances six steps while hardware executes eight updates. Full state matches the uninterrupted toy reference. Resetting only moments or only data/RNG changes the result.</p><p>The independent reference's final state is cursor=6, RNG=11, m=715 and weight accumulator=1350. Exact state matching here establishes only the toy recurrence. Real distributed validation compares sample IDs, target counts, loss, gradients, updates and backend-specific tolerances.</p>`)}
${section('determinism','Specify the reproducibility contract',`<p>Bitwise replay requires stable arithmetic order as well as restored random state. Reduction trees, kernel algorithms, routing tie-breaking and collective topology can change floating-point results. Pin the conditions the stack actually promises.</p><p>Statistical equivalence is weaker and often more practical across different hardware/layouts. Define acceptable numerical and behavioral tolerances, evaluation seeds and what differences trigger investigation. Do not claim exact replay after changing topology unless it is verified.</p><p>Compare uninterrupted and restored branches before the large run. Check FP8 history, tensor-parallel initialization/seeds, sampler position and complete optimizer state. Hashes are useful for exact contracts; matching one loss scalar is not enough.</p>`)}
${section('interval','Balance checkpoint pauses against replay',`${eq(String.raw`h(I)\approx\frac cI+\frac I{2M},\qquad I^*\approx\sqrt{2cM}`,'I is useful-work interval, c blocking checkpoint time, M mean time between independent failures. c>0, M>0 and I>0; all three share a time unit. Assumes rare failures and uniformly distributed progress lost within an interval.')}<p>Short intervals cost more saving time; long intervals lose more recent work. For assigned c=30 seconds and M=6 hours, I*≈1,138 seconds, or 19 minutes. The two overhead terms are each about 2.64% there.</p><p>This is a planning approximation, not a guarantee. Startup downtime, asynchronous interference, correlated faults, varying save cost and failure during saves require a richer model. With fully hidden I/O, effective blocking c can be small, while bandwidth and snapshot memory still constrain frequency.</p><p>Measure replay, checkpoint stalls and restore latency separately. Do not count the same replay in both an end-to-end throughput rate and a second goodput discount.</p>`)}
${section('elastic','Continue with fewer devices only under a contract',`<p>Gemma 4 describes slice-granularity elasticity on TPUs. After a localized failure, its larger models continue on fewer slices. The report describes reconfiguration delays falling from many minutes to seconds. This is source-specific infrastructure evidence, not a generic GPU recovery promise. ${cite('https://arxiv.org/html/2607.02770v1#S2.SS7','Gemma 4 §2.7')}</p><p>During a repair window R, reconfiguration time d and surviving throughput fraction r give approximate useful healthy-equivalent time r·max(0,R−d). Waiting idle gives zero work during that window. For assigned R=600s, d=20s and r=0.75, the degraded run earns 435 equivalent seconds.</p><p>That comparison assumes the same valid logical objective, no rollback and no extra rejoin cost. Charge repartitioning, data ownership, batch changes, communication inefficiency and restoration too. Changing replica count without preserving the intended global batch and reduction can change the experiment.</p>`)}
${section('telemetry','Join model and system telemetry',`${table('Correlate by global step, elapsed time and run branch',['Model/data signals','System signals'],[['Per-domain train/held-out loss; realized mixture','Input wait, queue depth, CPU and storage'],['Gradient/update norms, clipping rate, update-to-weight ratio; LR/batch','Step median/tail, compute/collective time, bubbles'],['Activation/logit scales; NaN/Inf; scaler','Peak memory, fragmentation, device health'],['Router usage, padding, entropy where relevant','Expert load, dispatch/combine, fabric congestion'],['Committed tokens and checkpoint lineage','Save duration, replay, startup and degraded placement']])}<p>Retain logs preceding an event. A loss spike, throughput drop and source-ratio change at the same step can guide investigation without identifying the cause. Compare a controlled branch before making a permanent recipe change.</p><p>Use tail latency, not only averages. One slow rank can hold the job. Assign an owner and response path to each important alert; a dashboard without action criteria is not a recovery system.</p>`)}
${section('evaluation','Use evaluation gates throughout the run',`<p>Run cheap fixed held-out NLL frequently. Schedule richer task suites and expert inspection less often. Use a complete final audit after any required post-training. Version prompts, dependencies, sampling, execution environments and scorer behavior.</p><p>For coding, include completion, infilling, repository editing, compile/execute checks and private held-out tasks. Use temporal/source separation and investigate suspicious benchmark gains. Add security, license and long-context checks where the product needs them.</p><p>Predeclare continuation and stop criteria: persistent regression, instability, unacceptable leakage, degraded goodput or an unreachable deadline. Do not select a metric after seeing which checkpoint wins. <a href="${link('math/statistics')}">Statistics and Evaluation →</a></p><p>Maintain an evaluation registry of prompts, solutions, repositories and known derivatives. Check exact and approximate overlap before tokenization; temporal holdouts depend on trustworthy timestamps. Include next-token loss by language/source, code memorization, long-range dependencies and expert review. Version the harness so a benchmark change is not mistaken for model progress.</p>`)}
${section('incidents','Respond to an incident with evidence',`<p>Preserve the preceding durable checkpoint, failing batch lineage and logs. Decide whether the run can safely continue while collecting evidence. Check inputs, resume state, masks/reductions, precision, gradient/update scales and hardware changes.</p><p>Reproduce a short branch with one intervention and a matched control. A lower learning rate can suppress a symptom while leaving a broken loader or collective untouched. Unrecorded skipped updates alter the token/schedule contract.</p><p>For low throughput, separate input wait, arithmetic, communication, bubbles and checkpoints. For unstable loss, separate source composition from domain degradation. For a failed resume, verify complete state before blaming optimization.</p><p><a href="${link('training/stability')}">Training Stability and Generalization →</a> contains clipping order, loss regimes and checkpoint diagnostics. The run plan supplies who responds, which evidence to retain and how recovery fits the remaining budget.</p><p>Replay the failing batch and neighboring batches from the same verified checkpoint, then compare a known-good batch. Data-correlated failure points toward the input path; persistence across batches warrants numerical and optimizer-state checks. Neither pattern identifies the cause by itself. Preserve the environment and use fewer ranks when a faithful reproduction is possible.</p><p>Quarantine a repeatedly failing node. Compare elastic continuation with waiting, including reconfiguration and rejoin costs. Compiler graph breaks, excessive logging and critical-path synchronization can reduce throughput without a hardware fault. Sunk tokens do not justify continuing a compromised trajectory; restart or stop when verified mitigation cannot protect the objective.</p>`)}
${section('serving','Validate the exported artifact',`<p>Convert the selected checkpoint under a versioned procedure. Validate tokenizer, control tokens, positions, attention masks, cache layout, precision and weight ownership against the training reference.</p><p>Run the actual serving stack, not only the training evaluator. Compare logits or outputs under an appropriate numerical contract, then test latency, memory and required context lengths. A faster kernel or quantized export can change behavior.</p><p>Keep the base, post-trained and serving artifacts distinct, with their lineage and evaluations. A completed training job is not a validated deployment. Finishing the run means producing a recoverable and interpretable artifact whose measured behavior meets the declared objective.</p>`)}
${section('sources','References and connected notes',`<p>${cite(smol,'Smol Training Playbook')} · ${cite(mai,'MAI-Thinking-1 report')} · ${cite(deepseek,'DeepSeek-V4.1 report')} · ${cite('https://arxiv.org/abs/2607.02770','Gemma 4 report')}</p><p>${cite('https://arxiv.org/abs/2203.15556','Chinchilla')} · ${cite('https://arxiv.org/abs/2001.08361','Kaplan scaling')} · ${cite('https://arxiv.org/abs/1909.08053','Megatron-LM')} · ${cite('https://arxiv.org/abs/2104.04473','Megatron distributed training')} · ${cite('https://arxiv.org/abs/1910.02054','ZeRO')} · ${cite('https://arxiv.org/abs/2205.05198','Reducing activation recomputation')} · ${cite('https://arxiv.org/abs/2101.00027','The Pile')} · ${cite('https://arxiv.org/abs/2107.06499','Deduplicating training data')} · ${cite('https://arxiv.org/abs/2406.11794','DataComp-LM')} · ${cite('https://jax-ml.github.io/scaling-book/','JAX scaling book')}</p><p>The worksheet, context bars, checkpoint interval and integer recovery trace are assigned explanatory models, not measured training results.</p><p><a href="${link('training/frontier-recipes')}#mai">MAI recipe →</a> · <a href="${link('training/frontier-recipes')}#deepseek-run">DeepSeek recipe →</a> · <a href="${link('training/data')}">Training Data →</a> · <a href="${link('execution/hardware')}">GPU Infrastructure →</a> · <a href="${link('execution/performance')}">Performance Accounting →</a></p>`)}
`);}
export function mountPractice(scope=document){mountTopic(scope,practiceMeta.slug,article=>{for(const name of ['budget','context','restart']){const lab=article.querySelector(`[data-practice-lab="${name}"]`),inputs=[...lab.querySelectorAll('input')],select=lab.querySelector('select'),draw=()=>{lab.querySelector('[data-body]').innerHTML=name==='budget'?budgetBody(Number(inputs[0].value),Number(select.value),Number(inputs[1].value)):name==='context'?contextBody(Number(inputs[0].value),Number(select.value)):recoveryBody(Number(inputs[0].value),select.value);};if(name==='restart'){const p=rangePlayback(article,lab,draw,15000);select.addEventListener('change',()=>{p.stop();draw();});}else{inputs.forEach(x=>x.addEventListener('input',draw));select.addEventListener('change',draw);}draw();}});}
practiceMeta.searchText=practiceReader(()=> '').replace(/<[^>]*>/g,' ');
